{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "TodoItem",
  "description": "A single todo item persisted in localStorage",
  "type": "object",
  "required": ["id", "title", "completed"],
  "properties": {
    "id": {
      "description": "A unique identifier for the todo item",
      "type": "string",
      "pattern": "^[a-zA-Z0-9_-]+$"
    },
    "title": {
      "description": "The todo item's text",
      "type": "string",
      "minLength": 1
    },
    "completed": {
      "description": "Whether the todo item is marked complete",
      "type": "boolean"
    }
  },
  "additionalProperties": false
}

{
  "watches": [
    {
      "watch": "empty-state",
      "scenarios": [
        "features/todos.feature:The main and footer sections are hidden when there are no todos"
      ]
    },
    {
      "watch": "create-todos",
      "scenarios": [
        "features/todos.feature:Create a new todo by typing and pressing Enter",
        "features/todos.feature:Leading and trailing whitespace is trimmed from new todo text",
        "features/todos.feature:An empty input does not create a todo"
      ]
    },
    {
      "watch": "complete-todos",
      "scenarios": [
        "features/todos.feature:Clicking the checkbox marks a todo as completed",
        "features/todos.feature:Toggling the last active todo updates the mark-all checkbox"
      ]
    },
    {
      "watch": "mark-all",
      "scenarios": [
        "features/todos.feature:The mark-all toggle marks every todo complete when none are complete",
        "features/todos.feature:The mark-all toggle marks every todo active when all are complete"
      ]
    },
    {
      "watch": "counter",
      "scenarios": [
        "features/todos.feature:The counter shows the number of active items with correct pluralization",
        "features/todos.feature:The counter number is wrapped in a strong tag"
      ]
    },
    {
      "watch": "clear-completed",
      "scenarios": [
        "features/todos.feature:The clear-completed button removes all completed todos",
        "features/todos.feature:The clear-completed button is hidden when there are no completed todos"
      ]
    },
    {
      "watch": "destroy",
      "scenarios": [
        "features/todos.feature:Hovering reveals the destroy button; clicking it removes the todo"
      ]
    },
    {
      "watch": "editing",
      "scenarios": [
        "features/todos.feature:Double-clicking a todo label activates editing mode",
        "features/todos.feature:Pressing Enter saves the edit and exits editing mode",
        "features/todos.feature:Blurring the edit input saves the edit",
        "features/todos.feature:Pressing Escape during editing discards the changes",
        "features/todos.feature:Clearing the edit text destroys the todo"
      ]
    },
    {
      "watch": "persistence",
      "scenarios": [
        "features/todos.feature:Todos are persisted to localStorage and survive a page reload",
        "features/todos.feature:Each persisted todo conforms to the todo item schema"
      ]
    },
    {
      "watch": "routing",
      "scenarios": [
        "features/todos.feature:The default route shows all todos",
        "features/todos.feature:The Active filter shows only uncompleted todos",
        "features/todos.feature:The Completed filter shows only completed todos",
        "features/todos.feature:Completing an item in the Active filter hides it",
        "features/todos.feature:Un-completing an item in the Completed filter hides it",
        "features/todos.feature:The selected class toggles on filter links when the route changes",
        "features/todos.feature:The active filter is persisted on reload"
      ]
    }
  ]
}

